size_t fn_18(const char *s, size_t n) {
  size_t i = 0;
  size_t j = 0;
  char stack[64];
  int in_string = 0;
  int in_comment = 0;
  while (i < n) {
    char c = s[i];
    if (in_comment) {
      if (c == '*' && s[i + 1] == '/') {
        in_comment = 0;
        i++;
      }
    } else if (in_string) {
      if (c == '"' && s[i + 1] != '"') {
        in_string = 0;
      }
    } else {
      switch (c) {
        case '\\':
          i++;
          if (i == n) {
            return n;
          }
          break;
        case '"':
          in_string = 1;
          break;
        case '{':
        case '[':
          if (j < 64) {
            stack[j++] = c == '{' ? '}' : ']';
          } else {
            return n;
          }
          break;
        case '}':
        case ']':
          if (j > 0 && stack[--j] == c) {
            break;
          } else {
            return n;
          }
        case '/':
          if (s[i + 1] == '*') {
            in_comment = 1;
            i++;
          }
          break;
        case ')':
          if (j > 0 && stack[--j] == '(') {
            break;
          } else {
            return n;
          }
      }
    }
    i++;
  }
  if (j == 0 && !in_comment) {
    return n;
  }
  return i;
}
